import fs from 'node:fs/promises';
import { chromium } from 'playwright';
const URL='https://www.statesideqm.com/collections/child-safety-shop?preview_theme_id=158561894555';
const OUT='cert-child-safety';
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function inspect(page,mobile){
 const browserErrors=[];page.on('pageerror',e=>browserErrors.push({type:'pageerror',message:e.message,stack:e.stack||''}));page.on('console',m=>{if(m.type()==='error')browserErrors.push({type:'console',message:m.text(),location:m.location()})});
 const response=await page.goto(URL,{waitUntil:'domcontentloaded',timeout:45000});try{await page.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',{timeout:20000})}catch{}await sleep(500);
 const data=await page.evaluate(()=>{const vis=el=>{if(!el)return false;const s=getComputedStyle(el),r=el.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&r.width>0&&r.height>0};const m=document.querySelector('#MainContent'),side=m?.querySelector('.sq-refine-v3-sidebar'),size=m?.querySelector('.sq-refine-v3-page-size'),grid=m?.querySelector('.product-grid'),groups=[...(side?.querySelectorAll('.sq-refine-v3-group')||[])],cards=[...(grid?.querySelectorAll(':scope>.product-grid__item')||[])].filter(x=>x.querySelector('a[href*="/products/"]'));const candidates=[];[...document.scripts].forEach((s,i)=>{const t=s.textContent||'';if(/function\s+build\s*\(/.test(t)&&t.includes('appendChild')){const p=t.indexOf('function build');candidates.push({index:i,attrs:[...s.attributes].map(a=>[a.name,a.value]),excerpt:t.slice(Math.max(0,p-500),p+3500)})}});return{title:document.title,ready:m?.dataset.sqRefineV3Ready||'',side:vis(side),titleText:side?.querySelector('.sq-refine-v3-sidebar__title')?.textContent.trim()||'',size:vis(size),sizes:[...(size?.querySelectorAll('input')||[])].map(x=>[x.value,x.checked]),groups:groups.map(g=>({label:g.querySelector(':scope>summary')?.textContent.trim()||'',inputs:g.querySelectorAll('input').length})),grid:vis(grid),cols:grid?getComputedStyle(grid).gridTemplateColumns.split(' ').filter(Boolean).length:0,cards:cards.length,sidePos:side?getComputedStyle(side).position:'',sideHeight:side?.getBoundingClientRect().height||0,legacy:[...document.querySelectorAll('[data-sq-refine-v3-hidden-nav="true"]')].filter(vis).length,candidates}});
 data.httpStatus=response?.status()||0;data.browserErrors=browserErrors;const errors=[];const fatal=browserErrors.filter(e=>e.type==='pageerror');if(fatal.length)errors.push(...fatal.map(e=>'browser '+JSON.stringify(e)));if(data.ready!=='true')errors.push('V3 not ready');if(!data.side||data.titleText!=='Refine Products')errors.push('sidebar');if(!data.size)errors.push('page size');if(data.sizes.map(x=>x[0]).join(',')!=='50,100,250')errors.push('page-size values');if(!data.groups.length)errors.push('no groups');if(data.legacy)errors.push('legacy='+data.legacy);if(!data.grid||!data.cards)errors.push('grid/cards');if(data.cols!==(mobile?2:3))errors.push('columns='+data.cols);if(!mobile&&data.sidePos!=='sticky')errors.push('desktop sticky');return{data,errors}}
 await fs.mkdir(OUT,{recursive:true});const browser=await chromium.launch({headless:true});const report={};for(const [name,viewport,mobile] of [['desktop',{width:1440,height:1000},false],['mobile',{width:390,height:844},true]]){const ctx=await browser.newContext({viewport});const p=await ctx.newPage();report[name]=await inspect(p,mobile);await p.screenshot({path:`${OUT}/${name}.png`,fullPage:true});await ctx.close()}await browser.close();report.pass=!report.desktop.errors.length&&!report.mobile.errors.length;await fs.writeFile(`${OUT}/report.json`,JSON.stringify(report,null,2));console.log(JSON.stringify(report,null,2));if(!report.pass)process.exitCode=1;
